const payload = $input.first().json || {};
const cc = payload.centralConfig || {};
const g = cc.globalConfig || {};
const bindingChecks = (((payload.centralConfigReadiness || {}).workflowBindingChecks) || []).map(b => ({ service: `Workflow Binding: ${b.key}`, key: b.key, ready: !!b.ready }));
const checks = [
  { service: 'Groq', key: 'groqApiKey', ready: !!g.groqApiKey && !String(g.groqApiKey).includes('PASTE_') },
  { service: 'Fliki', key: 'flikiApiKey', ready: !!g.flikiApiKey && !String(g.flikiApiKey).includes('PASTE_') },
  { service: 'Google Sheets', key: 'googleSheetId', ready: !!g.googleSheetId && !String(g.googleSheetId).includes('PASTE_') },
  { service: 'Upload-Post', key: 'uploadPostApiKey', ready: !!g.uploadPostApiKey && !String(g.uploadPostApiKey).includes('PASTE_') },
  { service: 'YouTube', key: 'youtubeChannelId', ready: !!g.youtubeChannelId && !String(g.youtubeChannelId).includes('PASTE_') },
  { service: 'Slack', key: 'slackWebhook', ready: !!g.slackWebhook && !String(g.slackWebhook).includes('PASTE_') },
  { service: 'Main Site', key: 'mainSiteUrl', ready: !!g.mainSiteUrl && !String(g.mainSiteUrl).includes('PASTE_') }
];
const allChecks = [...checks, ...bindingChecks];
return [{ json: { ...payload, readinessChecks: allChecks, readyCount: allChecks.filter(c => c.ready).length, totalChecks: allChecks.length } }];

const payload = $('Build Readiness Matrix').first().json || {};
const sheetRows = $input.all().map(i => i.json || {});
const checks = Array.isArray(payload.readinessChecks) ? payload.readinessChecks.slice() : [];
const sheetOk = !($input.first().json || {}).error;
checks.push({
  service: 'Google Sheets Read',
  key: 'sheetDashboard',
  ready: sheetOk,
  note: sheetOk ? 'Dashboard tab read succeeded or returned empty safely.' : String(($input.first().json || {}).error?.message || 'Google Sheets read failed')
});
const readyCount = checks.filter(c => c.ready).length;
const notReady = checks.filter(c => !c.ready).map(c => c.service);
return [{
  json: {
    workflowPackVersion: 'v23',
    serviceChecks: checks,
    readyCount,
    totalChecks: checks.length,
    notReady,
    nextStep: notReady.length ? `Finish or reconnect: ${notReady.join(', ')}` : 'Core readiness looks good. Next, run Setup Audit and then one manual content test per channel.'
  }
}];
